/// An entry as the reference pins it: its bytes, and its JSON form where it gives one.
type Pin = (&'static str, Option<&'static str>);

/// A second the reference marks: the save before it and after it, and its entries. An
/// event mark is the second `at` (the save before at `at − 1`); an input mark is an
/// `ArrangePartnership` stamped `at` (the saves before and after the input, at the stamp).
struct Mark {
    name: &'static str,
    at: i64,
    input: bool,
    before: &'static str,
    after: &'static str,
    entries: &'static [Pin],
}

/// A scenario: its data, its `Start`, its inputs and what the reference pins.
struct Scenario {
    tag: &'static str,
    separation: f64,
    /// The first year of the fertility window.
    fertile_from: f64,
    /// (age in years, sex) per founder; the step scenario's second founder is 16.5.
    founders: &'static [(i64, Sex)],
    couples: &'static [(u32, u32)],
    /// (stamp, woman, man) of each `ArrangePartnership`.
    inputs: &'static [(i64, u64, u64)],
    years: i64,
    data_hash: u64,
    after_start: &'static str,
    start_entries: &'static [Pin],
    marks: &'static [Mark],
    year_hashes: &'static [u64],
    log_hash: u64,
    log_entries: usize,
    end: &'static str,
}

